async fn orders(
    State(svc): State<Arc<OrderService>>,
    Query(page): Query<PageQuery>,
) -> Html<String> {
    let orders = svc.list(page.n).await;      // domain logic
    Html(render_orders(&orders))              // view selection
}

let app = Router::new()
    .route("/orders", get(orders))
    .layer(require_session())                 // shared behaviour
    .with_state(svc);
